<template>
  <div class="assetStatisticsChart">
    <v-chart ref="chartComponentRef" :option="chartOption" autoresize></v-chart>
  </div>
</template>
<script lang="ts">
import {defineComponent, reactive, toRefs, watch} from "vue";

export default defineComponent({
  name: "AssetStatisticsChart",
  props: {
    timeCountDataInfo: {
      type: Object,
      default: () => {
        return {};
      }
    },
    // 1: 光伏  2 储能
    scenarioType: {
      type: Number,
      default: 1
    }
  },
  setup(props) {

    const that = reactive({
      trafficWay: [
        {name: '总发电量', value: 0, fieldName: "totalQt", color: "#ADFEE5", scenarioType: 1},
        {name: '上网电量', value: 0, fieldName: "internetQt", color: "#30F3FF",scenarioType: 1},
        {name: '消纳电量', value: 0, fieldName: "absorptiveQt", color: "#ffa800",scenarioType: 1},

        {name: '储能充电量', value: 0, fieldName: "storageChargeQt", color: "#ADFEE5",scenarioType: 2},
        {name: '储能放电量', value: 0, fieldName: "storageDischargeQt", color: "#30F3FF",scenarioType: 2},
      ],

      returnDataInfo: {},

      chartOption: {
        backgroundColor: 'transparent',
        color: ['#ADFEE5', '#30F3FF', '#ffa800'],
        title: [{
          show: true,
          text: '消纳率',
          top: '50%',
          left: 'center',
          textStyle: {
            fontSize: 11,
            color: '#A1DDFE'
          }
        },{
          show: true,
          text: '0%',
          top: '35%',
          left: 'center',
          textStyle: {
            fontSize: 14,
            color: "#ffffff",
            fontWeight: "800"
          }
        }],
        graphic: {
          elements: [{
            type: "image",
            z: 3,
            style: {
              image: 'data:image/png;base64,',
              width: 80,
              height: 80
            },
            left: 'center',
            top: 'center',
            position: [100, 100]
          }]
        },
        series: [{
          type: 'pie',
          padAngle: 2,
          clockWise: false,
          hoverAnimation: false,
          radius: ['78%', '90%'],
          avoidLabelOverlap: false,
          label: {show: false},
          labelLine: {show: false},
          data: []
        }]
      }
    });

    const setChartDataFun = () => {
      let data = [];
      let chartOption = JSON.parse(JSON.stringify(that.chartOption));
      for (let i = 0; i < that.trafficWay.length; i++) {
        if(props.scenarioType === that.trafficWay[i].scenarioType){
          data.push({
            name: that.trafficWay[i].name,
            value: props.timeCountDataInfo[that.trafficWay[i].fieldName] ?? 0,
            itemStyle: {
              normal: {
                shadowBlur: 5,
                borderRadius: 2,
                borderWidth: 1,
                borderColor: that.trafficWay[i].color,
                shadowColor: that.trafficWay[i].color,
              }
            }
          });
        }
      }

      chartOption.series[0].data = data;
      if(props.scenarioType === 1){
        chartOption.title[0].text = '消纳率';
        chartOption.title[1].text = (props.timeCountDataInfo.absorptiveRate ?? 0)+ "%";
      }

      if(props.scenarioType === 2){
        chartOption.title[0].text = '系统充放电\n循环效率';
        chartOption.title[1].text = (props.timeCountDataInfo.systemEfficiency ?? 0)+ "%";
      }

      that.chartOption = JSON.parse(JSON.stringify(chartOption));
    };

    // 监听数据
    const watchTimeCountDataInfo = watch([()=>props.timeCountDataInfo,()=>props.scenarioType],([newTimeCountDataInfo])=>{
      // console.log(newTimeCountDataInfo);
      that.returnDataInfo = JSON.parse(JSON.stringify(newTimeCountDataInfo));
      setChartDataFun();
    },{ deep: true,immediate: true });

    return {...toRefs(that), setChartDataFun, watchTimeCountDataInfo};

  }
});
</script>
<style lang="scss" scoped>
.assetStatisticsChart {
  width: 140px;
  height: 140px;
  margin-left: 10px;
}
</style>